# Expected values generated by test/scipy/gen_integrate_ivp_expected.py (scipy 1.18.1).
# Tolerances: step/evaluation counts (nfev, njev, nlu, nst, nfe, nje) must
# match scipy exactly except where noted (LSODA paths: see CNT_TOL); solution values are compared with
# rtol 1e-9 (LSODA/BDF/Radau use a native LU instead of LAPACK so
# trajectories agree to rounding, ~1e-12, while long stiff runs accumulate
# up to ~1e-8 relative; see RTOL_STIFF).
import math
import numpy as np
from scipy import integrate as I

def close(x, ref, rtol: float = 1e-9, atol: float = 1e-14) -> bool:
    a = np.asarray(x).astype(float)
    r = np.asarray(ref).astype(float)
    if a.shape != r.shape:
        print('shape', a.shape, r.shape)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

FAILS = [0]
def check(name: str, ok: bool):
    if not ok:
        print('TEST FAILED', name)
        FAILS[0] += 1

RTOL_STIFF = 1e-5
# scipy's compiled lsoda.c is built with FMA contraction; the Typhon port is
# bit-identical to that C source compiled with -ffp-contract=off (checked with
# a C harness), so LSODA-based results (solve_ivp LSODA, odeint, ode) can
# differ by rounding, which occasionally changes step/evaluation counts. For
# those, counts are compared within CNT_TOL relative and values with RTOL_LS.
CNT_TOL = 0.06
RTOL_LS = 1e-6
def cnt(a, b) -> bool:
    x = np.asarray(a).astype(float)
    r = np.asarray(b).astype(float)
    if x.shape != r.shape:
        return False
    for u, v in zip(x.flat, r.flat):
        if abs(u - v) > CNT_TOL * abs(v) + 2:
            print('count mismatch', u, v)
            return False
    return True
