# ---------------------------------------------------------------- ode class
def f(t, y, a): return [y[1], -a*y[0]]
def jac(t, y, a): return [[0.0, 1.0], [-a, 0.0]]
r = I.ode(f, jac).set_integrator('lsoda', rtol=1e-8, atol=1e-10)
r.set_initial_value([1.0, 0.0], 0.0).set_f_params(2.0).set_jac_params(2.0)
outl: List[List[float]] = []
while r.successful() and r.t < 5.0:
    outl.append(r.integrate(r.t + 1.0).tolist())
check('ode lsoda', close(outl, ODE_LSODA[0], RTOL_LS, 1e-9) and r.t == ODE_LSODA[1] and r.get_return_code() == ODE_LSODA[2])
r2 = I.ode(f).set_integrator('lsoda')
r2.set_initial_value([1.0, 0.0], 0.0).set_f_params(2.0)
check('ode lsoda fd', close(r2.integrate(3.0), ODE_LSODA2, RTOL_LS, 1e-9))
# dopri5 / dop853 / vode: exact solution y0 = cos(sqrt(2) t), tolerance-level agreement
for name in ['dopri5', 'dop853', 'vode']:
    r3 = I.ode(f, jac).set_integrator(name, rtol=1e-10, atol=1e-12)
    r3.set_initial_value([1.0, 0.0], 0.0).set_f_params(2.0).set_jac_params(2.0)
    yv = r3.integrate(5.0)
    check('ode ' + name, r3.successful() and abs(yv[0] - math.cos(math.sqrt(2.0) * 5.0)) < 1e-7)
r4 = I.ode(f).set_integrator('vode', method='bdf', rtol=1e-8, atol=1e-10)
r4.set_initial_value([1.0, 0.0], 0.0).set_f_params(2.0)
yv = r4.integrate(5.0)
check('ode vode bdf', r4.successful() and abs(yv[0] - math.cos(math.sqrt(2.0) * 5.0)) < 1e-4)

if FAILS[0] == 0:
    print('integrate odeint ok')
